H=lambda id,cat,title,src,steps,tip="":dict(id=id,cat=cat,title=title,src=src,steps=steps,tip=tip)
G="Government IDs & documents";B="Benefits & loans";W="Work & business";L="Life & safety"
how=[H("mysss",B,"Create a My.SSS account","https://www.sss.gov.ph/",["Get your SSS number first (online SS number application on the SSS site) if you don't have one.","Go to the SSS website or the My.SSS app and choose Register.","Enter your SS number, name, birth date and an email you can open.","Confirm through the link/OTP sent to your email or phone, then set your password.","Log in to check contributions, loans and benefits. UMID/ID card applications are done through SSS; follow its current instructions."],"SSS never asks for your password by text or chat."),
H("ssscl",B,"Claim SSS benefits (sickness, maternity, unemployment, retirement)","https://www.sss.gov.ph/",["Log in to My.SSS and enroll a disbursement account (bank or e-wallet listed by SSS).","Check you have the required number of paid contributions for that benefit.","File the benefit online in My.SSS (or at a branch if required) and upload the documents asked.","Track the claim status in My.SSS; payment goes to your enrolled account."]),
H("mp2",B,"Save with Pag-IBIG MP2","https://www.pagibigfund.gov.ph/",["Be an active Pag-IBIG member (get your MID number via Virtual Pag-IBIG).","Enroll in MP2 online through Virtual Pag-IBIG and save your MP2 account number.","Pay through Virtual Pag-IBIG, accredited partners or a branch.","Dividends are announced yearly by Pag-IBIG; the term is 5 years."]),
H("pagloan",B,"Apply for a Pag-IBIG Multi-Purpose or Housing Loan","https://www.pagibigfund.gov.ph/",["Check eligibility (number of monthly savings and active membership) on the Pag-IBIG site.","Prepare a valid ID and proof of income.","Apply online through Virtual Pag-IBIG (multi-purpose/calamity) or submit housing loan requirements to a branch or developer.","Wait for approval; proceeds go to your Pag-IBIG Loyalty Card Plus or bank account."],"Beware of fixers. Pag-IBIG processing is done only through official channels."),
H("philhealth",B,"Register with PhilHealth and use benefits","https://www.philhealth.gov.ph/",["Register through the PhilHealth Member Portal or a PhilHealth office to get your PIN.","Update your contribution category (employed, self-employed, OFW, etc.).","Add qualified dependents.","When admitted to an accredited facility, present your PhilHealth ID/PIN so benefits are deducted from your bill."]),
H("philsys",G,"Get your PhilSys National ID","https://philsys.gov.ph/",["Register at a PhilSys registration center (check PSA/PhilSys announcements for sites near you).","Bring a valid supporting document (e.g., PSA birth certificate).","Have your biometrics taken.","Get your ePhilID or download the digital National ID when available; the physical card is delivered later."]),
H("passport",G,"Apply for a Philippine passport (DFA)","https://passport.gov.ph/",["Book an appointment only at the official DFA site (passport.gov.ph).","Pay the fee through the listed payment channels.","Bring your confirmation, PSA birth certificate (first-time) and a valid ID on your schedule.","Choose delivery or pick-up and track your passport."],"Only use passport.gov.ph. Fake booking sites exist."),
H("nbi",G,"Get an NBI clearance","https://clearance.nbi.gov.ph/",["Register at clearance.nbi.gov.ph.","Fill in your details and choose an NBI branch and schedule.","Pay through the listed channels.","Go to the branch for photo and fingerprints; with a 'HIT' you may need to return later."]),
H("police",G,"Get a police clearance","https://pnpclearance.ph/",["Register at the National Police Clearance System site.","Book a station and schedule, then pay online or at the station.","Bring two valid IDs; photo and fingerprints are taken at the station."]),
H("tin",W,"Register with BIR as a freelancer (TIN, Form 1901, 8% option)","https://www.bir.gov.ph/",["Register through BIR's ORUS online system or at your RDO using BIR Form 1901 (self-employed/professionals).","Choose your tax type. If gross sales/receipts are ₱3M or less, you may opt for the 8% income tax rate in your first quarter return.","Get your Certificate of Registration (Form 2303), register books of accounts and get authorized invoices.","File and pay quarterly/annual returns on time (eFPS/eBIRForms or accredited agents)."],"Tax rules change. Check BIR issuances or ask your RDO. Not tax advice."),
H("freelance",W,"Start freelancing safely","https://dict.gov.ph/",["Learn a skill with free courses (TESDA Online, DICT trainings).","Make an honest portfolio: show your real work only.","Use reputable platforms; never pay to 'get hired' and never share OTPs.","Use written contracts and milestone payments.","Register with BIR and keep records of income."],"If a job offer sounds too good, check SEC and DMW advisories."),
H("business",W,"Register a small business","https://bnrs.dti.gov.ph/",["Register your business name with DTI BNRS online (sole proprietor) or SEC (corporation/partnership).","Get a barangay clearance where your business is located.","Apply for a Mayor's/Business Permit at your city or municipal hall (BPLO).","Register with BIR (Form 1901 or 1903), get invoices and books.","Register employees with SSS, PhilHealth and Pag-IBIG if you hire."]),
H("license",G,"Get a driver's license (LTO LTMS)","https://portal.lto.gov.ph/",["Create an account on the LTO LTMS portal.","Take the required Theoretical Driving Course at an accredited driving school or LTO.","Apply for a Student Permit, then complete the Practical Driving Course.","Pass the written and practical exams at LTO for your Non-Professional/Professional license."]),
H("voter",G,"Register as a voter (COMELEC)","https://comelec.gov.ph/",["Check COMELEC announcements for the registration period (it stops before elections).","Fill out the application form (available online) and go to your local Election Officer with a valid ID.","Have your biometrics taken.","Check your precinct before election day."]),
H("psa",G,"Request a PSA birth certificate","https://www.psaserbilis.com.ph/",["Order online through PSA Serbilis (official PSA online service) or go to a PSA CRS outlet.","Fill in the details exactly as registered.","Pay through listed channels; delivery or pick-up follows.","For errors, ask your Local Civil Registrar about correction (RA 9048/10172)."]),
H("scholar",L,"Apply for scholarships: tips","https://ched.gov.ph/",["List scholarships that fit you (see Civi Scholarships: local and abroad).","Check eligibility and deadlines on the official page only.","Prepare documents early: grades, PSA birth certificate, income proof, essay.","Submit before the deadline and keep copies.","Never pay 'processing fees' to unofficial agents."]),
H("disaster",L,"Prepare a disaster go-bag","https://ocd.gov.ph/",["Pack water, ready-to-eat food, flashlight, batteries and a whistle.","Add first aid kit, maintenance medicines, face masks, and hygiene items.","Keep copies of IDs and documents in a waterproof bag, plus some cash.","Know your evacuation center and family meeting place.","Follow PAGASA, PHIVOLCS and your LGU for warnings."]),
H("foi",L,"Request government documents (FOI)","https://www.foi.gov.ph/",["Find the agency on foi.gov.ph.","Describe exactly the document you want and why.","Submit and track your request online.","Agencies normally reply within the period set by the FOI rules; you can appeal a denial."])]
json.dump(dict(as_of=AS_OF,note="Steps are a simple guide as of the date shown. Requirements and fees change: always check the official site before you go.",items=how),open("data/howto.json","w"),ensure_ascii=False,indent=0)
print(len(gov),len(off),len(co),len(how))
